#include <fstream>
#include <sys/stat.h>
#include <unistd.h>
#include <string>
#include <cerrno>
#include <cstring>

void saveSecreteFile(const std::string& directory, const std::string& filename, const std::string& content) {
    std::string fullPath = directory + "/" + filename;

    // Check if directory exists and is writable
    struct stat st;
    if (stat(directory.c_str(), &st) != 0 || !(st.st_mode & S_IWUSR)) {
        std::cerr << "Error: Directory does not exist or is not writable: " << directory << std::endl;
        return;
    }

    std::ofstream file(fullPath);
    if (file.is_open()) {
        file << content;
        file.close();
        // Set file permissions to be readable and writable only by the owner
        if (chmod(fullPath.c_str(), S_IRUSR | S_IWUSR) != 0) {
            std::cerr << "Error: Failed to set file permissions: " << fullPath << std::endl;
        }
    } else {
        std::cerr << "Error: Failed to open file: " << fullPath << std::endl;
    }
}

